/* Roboto (Apache-2.0) embedded as base64 for the CorelDRAW-safe vector ID-card PDF
   generator. Embedding means the PDF never depends on the viewer's fonts and
   every glyph is a real text glyph (editable + searchable in CorelDRAW). */
window.SC_PDF_FONTS = window.SC_PDF_FONTS || {
  'Roboto-Regular': '',
  'Roboto-Bold': ''
};
